import { BUILT_IN_ACTIONS } from "../shared/defaults";
import { addHistoryItem, getSettings, toggleHistoryFavorite } from "../shared/storage";
import type { AiRequest, StreamChunk } from "../shared/types";
import { getAdapter } from "./providers";

const rateLimit = new Map<number, number[]>();
const MAX_REQUESTS_PER_MINUTE = 12;

function isRateLimited(senderId: number): boolean {
  const now = Date.now();
  const recent = (rateLimit.get(senderId) ?? []).filter((timestamp) => now - timestamp < 60_000);
  recent.push(now);
  rateLimit.set(senderId, recent);
  return recent.length > MAX_REQUESTS_PER_MINUTE;
}

async function sendTabMessage(tabId: number, message: unknown): Promise<void> {
  try {
    await chrome.tabs.sendMessage(tabId, message);
  } catch {
    // Content scripts cannot run on restricted pages (chrome://, extension pages, etc.).
  }
}

chrome.runtime.onInstalled.addListener(() => {
  chrome.contextMenus.removeAll(() => {
    [
      ["open-assistant", "Open AI Context Assistant"],
      ["translate-selection", "Translate Selection"]
    ].forEach(([id, title]) => chrome.contextMenus.create({ id, title, contexts: ["selection"] }));
  });
});

chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (!tab?.id || !info.selectionText) return;
  const actionByMenu: Record<string, string> = {
    "open-assistant": "open",
    "translate-selection": "translate"
  };
  void sendTabMessage(tab.id, {
    type: "CONTEXT_MENU_ACTION",
    actionId: actionByMenu[String(info.menuItemId)] ?? "normal",
    text: info.selectionText
  });
});

chrome.commands.onCommand.addListener(async (command, tab) => {
  if (!tab?.id) return;
  void sendTabMessage(tab.id, {
    type: "RUN_SHORTCUT_OPEN"
  });
});

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message.type === "OPEN_SETTINGS") {
    chrome.tabs.create({ url: chrome.runtime.getURL("settings.html") });
  }
  if (message.type === "OPEN_HISTORY") {
    chrome.tabs.create({ url: chrome.runtime.getURL("history.html") });
  }
  if (message.type === "TOGGLE_HISTORY_FAVORITE" && message.id) {
    void toggleHistoryFavorite(message.id).then(() => sendResponse({ ok: true }));
    return true;
  }
});

chrome.runtime.onConnect.addListener((port) => {
  if (port.name !== "ai-stream") return;
  port.onMessage.addListener(async (request: AiRequest) => {
    try {
      const tabId = port.sender?.tab?.id ?? 0;
      if (isRateLimited(tabId)) throw new Error("Too many requests. Please wait a moment and try again.");
      const settings = await getSettings();
      const adapter = getAdapter(settings.provider.provider);
      const result = await adapter.stream(request, settings.provider, (text) => {
        port.postMessage({ type: "chunk", id: request.id, text } satisfies StreamChunk);
      });
      const action = [...BUILT_IN_ACTIONS, ...settings.customActions].find((item) => item.id === request.actionId);
      await addHistoryItem({
        id: request.id,
        createdAt: Date.now(),
        actionName: action?.name ?? request.actionName ?? "Custom",
        prompt: request.instruction,
        mode: request.mode,
        provider: settings.provider.provider,
        model: settings.provider.model,
        selection: request.selection,
        result
      });
      port.postMessage({ type: "done", id: request.id } satisfies StreamChunk);
    } catch (error) {
      port.postMessage({
        type: "error",
        id: request.id,
        error: error instanceof Error ? error.message : "AI request failed."
      } satisfies StreamChunk);
    }
  });
});
