import type { AiRequest, ProviderConfig } from "../shared/types";
import { DEFAULT_PROVIDER_MODEL } from "../shared/models";
import { buildMessages } from "./prompts";

export interface AiProviderAdapter {
  stream(request: AiRequest, config: ProviderConfig, onChunk: (text: string) => void): Promise<string>;
}

async function providerError(response: Response): Promise<Error> {
  const body = await response.text();
  if (response.status === 429) {
    const retryHeader = Number(response.headers.get("retry-after"));
    const retryFromBody = body.match(/retryDelay"?\s*:\s*"?(\d+)s/i)?.[1] ?? body.match(/retry.*?(\d+)\s*seconds?/i)?.[1];
    const seconds = Number.isFinite(retryHeader) && retryHeader > 0 ? retryHeader : Number(retryFromBody || 52);
    return new Error(`RATE_LIMIT:${seconds}`);
  }
  return new Error(body || `Provider request failed with ${response.status}`);
}

async function readSse(response: Response, onChunk: (text: string) => void, pick: (json: unknown) => string): Promise<string> {
  if (!response.ok || !response.body) {
    throw await providerError(response);
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let full = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line.startsWith("data:")) continue;
      const data = line.slice(5).trim();
      if (!data || data === "[DONE]") continue;
      const text = pick(JSON.parse(data));
      if (text) {
        full += text;
        onChunk(text);
      }
    }
  }
  return full;
}

export const openAiAdapter: AiProviderAdapter = {
  async stream(request, config, onChunk) {
    if (!config.apiKey) throw new Error("Add an OpenAI API key in settings.");
    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${config.apiKey}`
      },
      body: JSON.stringify({
        model: config.model || DEFAULT_PROVIDER_MODEL.openai,
        messages: buildMessages(request),
        stream: true,
        temperature: request.mode === "creative" ? 0.85 : 0.25
      })
    });
    return readSse(response, onChunk, (json) => {
      const payload = json as { choices?: Array<{ delta?: { content?: string } }> };
      return payload.choices?.[0]?.delta?.content ?? "";
    });
  }
};

export const claudeAdapter: AiProviderAdapter = {
  async stream(request, config, onChunk) {
    if (!config.apiKey) throw new Error("Add a Claude API key in settings.");
    const messages = buildMessages(request);
    const system = messages.find((message) => message.role === "system")?.content ?? "";
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": config.apiKey,
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true"
      },
      body: JSON.stringify({
        model: config.model || DEFAULT_PROVIDER_MODEL.claude,
        system,
        messages: messages.filter((message) => message.role !== "system"),
        stream: true,
        max_tokens: 1200,
        temperature: request.mode === "creative" ? 0.8 : 0.2
      })
    });
    return readSse(response, onChunk, (json) => {
      const payload = json as { type?: string; delta?: { text?: string } };
      return payload.type === "content_block_delta" ? payload.delta?.text ?? "" : "";
    });
  }
};

export const geminiAdapter: AiProviderAdapter = {
  async stream(request, config, onChunk) {
    if (!config.apiKey) throw new Error("Add a Gemini API key in settings.");
    const messages = buildMessages(request);
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${config.model || DEFAULT_PROVIDER_MODEL.gemini}:streamGenerateContent?key=${config.apiKey}&alt=sse`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: messages.map((message) => ({
          role: message.role === "assistant" ? "model" : "user",
          parts: [{ text: `${message.role.toUpperCase()}:\n${message.content}` }]
        })),
        generationConfig: { temperature: request.mode === "creative" ? 0.8 : 0.2 }
      })
    });
    return readSse(response, onChunk, (json) => {
      const payload = json as { candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }> };
      return payload.candidates?.[0]?.content?.parts?.[0]?.text ?? "";
    });
  }
};

export const ollamaAdapter: AiProviderAdapter = {
  async stream(request, config, onChunk) {
    const response = await fetch(`${config.baseUrl || "http://127.0.0.1:11434"}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: config.model || DEFAULT_PROVIDER_MODEL.ollama,
        messages: buildMessages(request),
        stream: true
      })
    });
    if (!response.ok || !response.body) throw await providerError(response);
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let full = "";
    let buffer = "";
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";
      for (const line of lines) {
        if (!line.trim()) continue;
        const payload = JSON.parse(line) as { message?: { content?: string } };
        const text = payload.message?.content ?? "";
        full += text;
        onChunk(text);
      }
    }
    return full;
  }
};

export function getAdapter(provider: ProviderConfig["provider"]): AiProviderAdapter {
  return {
    openai: openAiAdapter,
    gemini: geminiAdapter,
    claude: claudeAdapter,
    ollama: ollamaAdapter
  }[provider];
}
