import { CREATIVE_MODE_PROMPT, NORMAL_MODE_PROMPT } from "../shared/defaults";
import type { AiRequest } from "../shared/types";

export function buildMessages(request: AiRequest) {
  const modePrompt = request.mode === "creative" ? CREATIVE_MODE_PROMPT : NORMAL_MODE_PROMPT;
  const smartHint = {
    code: "The selection looks like code. Explain behavior, risks, edge cases, and keep identifiers intact.",
    email: "The selection looks like an email. Preserve intent and make the tone appropriate.",
    article: "The selection looks like a longer article. Prioritize structure and the central argument.",
    tweet: "The selection looks like a social post. Keep it punchy and context-aware.",
    text: "Treat the selection as general text."
  }[request.selection.kind];

  const system = [
    "You are AI Context Assistant, a fast in-browser helper for selected text.",
    modePrompt,
    smartHint,
    "Use the page context when helpful, preserve formatting when transforming text, and never invent source facts.",
    `Detected language: ${request.selection.language}. Page: ${request.selection.pageTitle} (${request.selection.pageUrl}).`
  ].join("\n");

  const user = [
    `Instruction: ${request.instruction}`,
    request.targetLanguage ? `Translation target language: ${request.targetLanguage}` : "",
    request.sourceLanguage ? `Translation source language: ${request.sourceLanguage}` : "",
    request.translationContext
      ? `Translation Context: ${request.translationContext}\nThis context is high priority. It should strongly control tone, terminology, formality, and phrasing.`
      : "",
    request.selection.surroundingText ? `Nearby context:\n${request.selection.surroundingText}` : "",
    `Selected text:\n${request.selection.text}`
  ]
    .filter(Boolean)
    .join("\n\n");

  return [
    { role: "system" as const, content: system },
    ...request.memory,
    { role: "user" as const, content: user }
  ];
}
